struct ToneMsg {
  static constexpr FrameType kType = FrameType::kTone;
  static constexpr uint8_t kFixedSize = 1;
  static constexpr uint8_t kMaxSize = 41;
  uint8_t n;
  ToneNotesItem notes[10];
};

inline uint8_t encode(const ToneMsg& m, uint8_t* out) {
  if (m.n > 10) { return kEncodeError; }
  uint8_t* p = out;
  put_u8(p, static_cast<uint8_t>(m.n));
  for (uint8_t i = 0; i < m.n; ++i) {
    put_u16(p, static_cast<uint16_t>(m.notes[i].hz));
    put_u16(p, static_cast<uint16_t>(m.notes[i].ms));
  }
  return static_cast<uint8_t>(p - out);
}

inline bool decode(const uint8_t* in, uint8_t len, ToneMsg& m) {
  if (len < ToneMsg::kFixedSize) { return false; }
  const uint8_t* p = in;
  m.n = static_cast<uint8_t>(get_u8(p));
  if (m.n > 10 || len != ToneMsg::kFixedSize + m.n * 4) { return false; }
  for (uint8_t i = 0; i < m.n; ++i) {
    m.notes[i].hz = static_cast<uint16_t>(get_u16(p));
    m.notes[i].ms = static_cast<uint16_t>(get_u16(p));
  }
  return true;
}

